  "locale:23843 [npc_dialog | - | Troll] '#Cap([*player*]) found out that trolls like to collect things. Unfortunately, instead of butterflies or coins, trolls like to collect people!'",
  "locale:23846 [npc_dialog | - | Queen] 'You hear news? Queen demands grapes now. Grapes coming all the way from Sanctuary!'",
  "locale:23847 [npc_dialog | - | Troll NPCs] 'Me like to be that delivery troll. Village is hard life now.'",
  "locale:23848 [npc_dialog | - | Troll NPCs] 'I wonder what being soldier is like?'",
  "locale:23849 [npc_dialog | - | Troll NPCs] 'Good. Me think being soldier would be easy. Sit all day and eat food and drink water we be getting all day and night.'",
  "locale:23850 [npc_dialog | - | Troll NPCs] 'Queen is mean. Me miss Grosh, he was nice King.'",
  "locale:23851 [npc_dialog | - | Troll NPCs] 'Is tiring to walk all day. Me hungry and sore.'",
  "locale:23852 [npc_dialog | - | Troll NPCs] 'Just a bit longer, maybe Hogosh let us rest this time.'",
  "locale:23853 [npc_dialog | - | Troll NPCs] 'Water carriers! Get back to work!'",
  "locale:23854 [npc_dialog | - | Troll NPCs] 'Here we go again.'",
  "locale:23855 [npc_dialog | - | Hogosh] 'Hogosh be strong, but maybe not so smart.'",
  "locale:23856 [npc_dialog | - | Troll NPCs] 'He seems smart to me. Queen likes him.'",
  "locale:23857 [npc_dialog | - | Troll NPCs] 'Maybe, but we could run any time.'",
  "locale:23858 [npc_dialog | - | Troll NPCs] 'Where we go? No one likes trolls, because they hear about mean Queen and Hogosh.'",
  "locale:23859 [npc_dialog | - | Gulsh] 'Gulsh moved to Sanctuary. Maybe he help us?'",
  "locale:23860 [npc_dialog | - | Troll NPCs] 'When will we rest?'",
  "locale:23861 [npc_dialog | - | Hogosh] 'Not this time. Hogosh to busy playing cards to know we to tired to continue.'",
  "locale:23862 [npc_dialog | - | Troll NPCs] 'We should rest at river this time. Maybe they not notice if we take longer.'",
  "locale:23863 [npc_dialog | - | Troll NPCs] \"Yes. Let's stop and rest.\"",
  "locale:23864 [npc_dialog | - | Gulsh] 'You really think Gulsh help us?'",
  "locale:23865 [npc_dialog | - | Troll NPCs] 'Maybe, he was good brother to one of the cooks.'",
  "locale:23866 [npc_dialog | - | Troll NPCs] 'Me miss old days. Life was good with Grosh as King.'",
  "locale:23867 [npc_dialog | - | Gulsh] 'Gulsh take tolls from people going to Sanctuary. Maybe he have money to feed everyone.'",
  "locale:23868 [npc_dialog | - | Troll NPCs] 'This be home. Someone will defeat Queen one day and we be happy again.'",
  "locale:23870 [quest_dialog | - | Special Delivery] \"Great job with that Special Delivery. Now that you've completed that challenge, you're always welcome to help with it again.\""
 ],
