 "lines_to_bind": [
  "locale:100181 [npc_dialog | Seaside | Seaside lifeguard] \"It sure is nice to be on a break. It's been a busy shift.\"",
  "locale:100182 [npc_dialog | Seaside | Seaside lifeguard] 'Tell me about it! All these people on the beach make being a lifeguard pretty hectic.'",
  "locale:100183 [npc_dialog | Seaside | Seaside lifeguard] \"I haven't been on this job long. Do you guys have any exciting stories to tell?\"",
  "locale:100186 [npc_dialog | Seaside | Seaside lifeguard] \"Oh, I have one you won't believe!\"",
  "locale:100187 [npc_dialog | Seaside | Seaside lifeguard] 'Once while on duty, I heard a girl scream for help. I ran to the shore and saw she was being attacked by a man-eating shark!'",
  "locale:100192 [npc_dialog | Seaside | Seaside lifeguard] 'Oh wow! What did you do next?'",
  "locale:100193 [npc_dialog | Seaside | Seaside lifeguard] 'Without fear, I jumped in the water to save her, just as the shark was closing in!'",
  "locale:100194 [npc_dialog | Seaside | Seaside lifeguard] 'And then?'",
